import sys


def is_valid(line: str) -> bool:
    stack = []
    matching = {")": "(", "]": "[", "}": "{"}

    for bracket in line:
        if bracket in "([{":
            stack.append(bracket)
        elif not stack or stack.pop() != matching[bracket]:
            return False

    return not stack


def main() -> None:
    input_stream = sys.stdin
    first_line = input_stream.readline()
    if not first_line:
        return

    line_count = int(first_line)
    results = []
    for _ in range(line_count):
        line = input_stream.readline().rstrip("\r\n")
        results.append("valid" if is_valid(line) else "invalid")

    if results:
        sys.stdout.write("\n".join(results) + "\n")


if __name__ == "__main__":
    main()

