import sys


def main() -> None:
    lines = sys.stdin.buffer
    first = lines.readline()
    if not first:
        return

    count = int(first)
    numbers = [int(lines.readline()) for _ in range(count)]
    parts: list[str] = []
    index = 0

    while index < count:
        end = index
        while end + 1 < count and numbers[end + 1] == numbers[end] + 1:
            end += 1

        if end - index + 1 >= 3:
            parts.append(f"{numbers[index]}-{numbers[end]}")
        else:
            parts.extend(str(numbers[position]) for position in range(index, end + 1))

        index = end + 1

    sys.stdout.write(",".join(parts) + "\n")


if __name__ == "__main__":
    main()

